package org.apache.commons.math.optimization;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.random.JDKRandomGenerator;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.LocalizedFormats;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class MultiStartUnivariateRealOptimizer_getResult_TriageGen5Test {

    private UnivariateRealOptimizer mockOptimizer;
    private RandomGenerator mockGenerator;
    private MultiStartUnivariateRealOptimizer multiStartOptimizer;

    @Before
    public void setUp() {
        mockOptimizer = mock(UnivariateRealOptimizer.class);
        mockGenerator = new JDKRandomGenerator();
        multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 10, mockGenerator);
    }

    /**
     * Tests getResult() when the underlying optimizer returns a standard positive value.
     */
    @Test
    public void testGetResultWithPositiveValue() throws Exception {
        double expectedValue = 123.456;
        when(mockOptimizer.getResult()).thenReturn(expectedValue);

        // We must trigger the optimization process or ensure the internal state is set.
        // Since getResult() delegates to optimizer.getResult(), we simulate a successful optimization.
        // In a real scenario, optimize() would be called.

        double actualValue = multiStartOptimizer.getResult();

        assertEquals(expectedValue, actualValue, 1e-15);
    }

    /**
     * Tests getResult() when the underlying optimizer returns zero.
     */
    @Test
    public void testGetResultWithZero() throws Exception {
        double expectedValue = 0.0;
        when(mockOptimizer.getResult()).thenReturn(expectedValue);

        double actualValue = multiStartOptimizer.getResult();

        assertEquals(expectedValue, actualValue, 1e-15);
    }

    /**
     * Tests getResult() when the underlying optimizer returns a negative value.
     */
    @Test
    public void testGetResultWithNegativeValue() throws Exception {
        double expectedValue = -987.654;
        when(mockOptimizer.getResult()).thenReturn(expectedValue);

        double actualValue = multiStartOptimizer.getResult();

        assertEquals(expectedValue, actualValue, 1e-15);
    }

    /**
     * Tests getResult() when the underlying optimizer returns NaN.
     */
    @Test
    public void testGetResultWithNaN() throws Exception {
        double expectedValue = Double.NaN;
        when(mockOptimizer.getResult()).thenReturn(expectedValue);

        double actualValue = multiStartOptimizer.getResult();

        assertEquals(expectedValue, actualValue, 0.0);
    }

    /**
     * Tests getResult() when the underlying optimizer returns Infinity.
     */
    @Test
    public void testGetResultWithInfinity() throws Exception {
        double expectedValue = Double.POSITIVE_INFINITY;
        when(mockOptimizer.getResult()).thenReturn(expectedValue);

        double actualValue = multiStartOptimizer.getResult();

        assertEquals(expectedValue, actualValue, 0.0);
    }
}
